def prem_anchor_key():
    """The (issue_age, term_y) key of the is_anchor row of this policy's sex in prem_rate_table."""
    sub = data.prem_rate_table().loc[sex()]                          # noqa: F821
    return min(k for k in sub.index if sub.loc[k, "is_anchor"] == 1)
